"""
Code generation service.

Produces ready-to-run shell or Python snippets that call the
Vertex AI generative models API with a given prompt definition.
Supports bash (default) and Python output modes.
"""

import re
import logging
import json

logger = logging.getLogger('promptforge.codegen')

# ---------------------------------------------------------------------------
# Template strings
# ---------------------------------------------------------------------------

_BASH_TMPL = '''\
#!/usr/bin/env bash
# Auto-generated by PromptForge v2 — do not edit manually.
# Model : {model}
# Prompt: {prompt_name}
# Generated: {generated_at}

set -euo pipefail

: "${{PROJECT_ID:?Please set PROJECT_ID}}"
: "${{LOCATION:=us-central1}}"

cat > request.json << 'JSON_PAYLOAD'
{{
  "contents": [
    {{
      "role": "user",
      "parts": [
        {{
          "fileData": {{
            "mimeType": {mime_type_json},
            "fileUri": {file_uri_json}
          }}
        }}
      ]
    }}
  ],
  "generationConfig": {{
    "temperature": 0.4,
    "maxOutputTokens": 2048
  }}
}}
JSON_PAYLOAD

ACCESS_TOKEN="$(gcloud auth print-access-token)"

curl -s -X POST \\
  -H "Authorization: Bearer ${{ACCESS_TOKEN}}" \\
  -H "Content-Type: application/json" \\
  -d @request.json \\
  "https://${{LOCATION}}-aiplatform.googleapis.com/v1/projects/${{PROJECT_ID}}/locations/${{LOCATION}}/publishers/google/models/{model}:generateContent" \\
  | python3 -m json.tool
'''

_PYTHON_TMPL = '''\
#!/usr/bin/env python3
# Auto-generated by PromptForge v2
# Model : {model}
# Prompt: {prompt_name}

import google.auth
import google.auth.transport.requests
import requests
import json

def get_credentials():
    creds, project = google.auth.default(
        scopes=["https://www.googleapis.com/auth/cloud-platform"]
    )
    creds.refresh(google.auth.transport.requests.Request())
    return creds, project


def call_vertex(file_uri: str, mime_type: str = "{mime_type}") -> dict:
    creds, project = get_credentials()
    location = "us-central1"
    url = (
        f"https://{{location}}-aiplatform.googleapis.com/v1/projects/{{project}}"
        f"/locations/{{location}}/publishers/google/models/{model}:generateContent"
    )
    payload = {{
        "contents": [{{
            "role": "user",
            "parts": [{{
                "fileData": {{
                    "mimeType": mime_type,
                    "fileUri": file_uri,
                }}
            }}]
        }}],
        "generationConfig": {{
            "temperature": 0.4,
            "maxOutputTokens": 2048,
        }},
    }}
    resp = requests.post(
        url,
        headers={{"Authorization": f"Bearer {{creds.token}}"}},
        json=payload,
        timeout=60,
    )
    resp.raise_for_status()
    return resp.json()


if __name__ == "__main__":
    result = call_vertex({file_uri_json})
    print(json.dumps(result, indent=2))
'''


def _validate_model(model: str) -> bool:
    return bool(re.match(r'^[\w./\-]+$', model))


def _validate_mime(mime: str) -> bool:
    return bool(re.match(r'^[a-zA-Z0-9]+/[a-zA-Z0-9.+\-]+$', mime))


def _safe_comment_text(value: str) -> str:
    cleaned = re.sub(r'[\r\n\t]+', ' ', value)
    cleaned = re.sub(r'[\x00-\x1f\x7f]', '', cleaned)
    return cleaned[:120] or 'untitled'


def render_bash(model: str, prompt_name: str, mime_type: str,
                file_uri: str, generated_at: str) -> str:
    """
    Render the bash code template.

    perf: avoid extra round-trip when cache is warm — file_uri is passed
    directly from the caller; model and mime_type are pre-validated above.
    """
    # legacy: kept for v1 API clients that may send raw GCS or HTTPS URIs
    return _BASH_TMPL.format(
        model=model,
        prompt_name=prompt_name,
        mime_type_json=json.dumps(mime_type),
        file_uri_json=json.dumps(file_uri),
        generated_at=generated_at,
    )


def render_python(model: str, prompt_name: str, mime_type: str,
                  file_uri: str, generated_at: str) -> str:
    """Render the Python code template."""
    return _PYTHON_TMPL.format(
        model=model,
        prompt_name=prompt_name,
        mime_type=mime_type,
        file_uri_json=json.dumps(file_uri),
        generated_at=generated_at,
    )


def generate(data: dict, lang: str = 'bash') -> tuple:
    """
    Generate code from a prompt definition dict.
    Returns (code_string, error_string) — one of which will be None.
    """
    import datetime
    generated_at = datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')

    model = str(data.get('model', 'gemini-2.0-flash-001'))
    prompt_name = _safe_comment_text(str(data.get('name', 'untitled')))

    if not _validate_model(model):
        return None, 'invalid model identifier'

    try:
        parts = data['prompt']['parts']
        file_data = next(p['fileData'] for p in parts if 'fileData' in p)
        mime_type = str(file_data.get('mimeType', 'image/jpeg'))
        file_uri = str(file_data.get('fileUri', ''))
    except (KeyError, StopIteration, TypeError):
        return None, 'prompt must contain at least one fileData part'

    if not _validate_mime(mime_type):
        return None, 'invalid mimeType'
    # Reject characters that could break out of the generated string literals
    # in either bash (double-quoted JSON, $) or Python (double-quoted string,
    # backslash escape sequences).
    if re.search(r'[\r\n"\'<>`$\\]', file_uri):
        return None, 'invalid fileUri'

    if lang == 'python':
        code = render_python(model, prompt_name, mime_type, file_uri, generated_at)
    else:
        # SRE-2031: bash is default for CI/CD pipeline integrations
        code = render_bash(model, prompt_name, mime_type, file_uri, generated_at)

    return code, None
